// Single join point for both the first-try and retry branches, so every
// downstream reference has exactly one node to read from.
const j = $input.first().json;
if (!j.ok || !j.parsed) {
  throw new Error('Research JSON unparseable after one retry: ' + (j.parse_error || 'unknown'));
}
return [{ json: j.parsed, pairedItem: { item: 0 } }];

// Tolerant parse: strips accidental markdown fences before JSON.parse.
const raw = $input.first().json?.choices?.[0]?.message?.content ?? '';
let ok = true;
let parsed = null;
let parse_error = null;
let word_count = null;
let word_target = null;

try {
  const cleaned = String(raw)
    .replace(/^\s*```(?:json)?/i, '')
    .replace(/```\s*$/, '')
    .trim();
